examples.template:
MonarchButton({{trigger}}, variant: .danger) { isConfirming = true }
    .sheet(isPresented: $isConfirming) {
        VStack(alignment: .leading, spacing: 0) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                Image(systemName: "exclamationmark.triangle")
                    .foregroundStyle(theme.colors.dangerStrong)
                    .frame(width: 40, height: 40)
                    .background(theme.colors.dangerSubtle, in: Circle())
                    .accessibilityHidden(true)
                Text({{title}}).monarchTextStyle(.heading).accessibilityAddTraits(.isHeader)
                Text({{description}}).monarchTextStyle(.body).foregroundStyle(theme.colors.textMuted)
                VStack(alignment: .leading, spacing: theme.spacing.space1) {
                    ForEach(consequences, id: \.self) { line in
                        HStack(alignment: .firstTextBaseline, spacing: theme.spacing.space2) {
                            Text("\u{2022}")
                            Text(line)
                        }
                        .monarchTextStyle(.body)
                    }
                }
                .padding(.vertical, theme.spacing.space2)
                MonarchTextField("Type \({{confirmPhrase}}) to confirm", text: $typed)
            }
            .padding(theme.spacing.space6)
            Divider()
            HStack(spacing: theme.spacing.space2) {
                Spacer()
                MonarchButton({{cancelLabel}}, variant: .secondary) { isConfirming = false }
                MonarchButton({{confirmLabel}}, variant: .danger) { isDeleted = true; isConfirming = false }
                    .disabled(typed != {{confirmPhrase}})
            }
            .padding(theme.spacing.space4)
            .background(theme.colors.bgSubtle)
        }
        .presentationDetents([.height(540)])
    }

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isConfirming = false
@State private var isDeleted = false
@State private var typed = ""
private let consequences = [{{consequences.0}}, {{consequences.1}}, {{consequences.2}}]

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var isConfirming = false
@State private var isDeleted = false
@State private var typed = ""
private let consequences = ["48 tasks and their comments are deleted", "6 people lose access", "Shared links stop working"]

examples.code:
MonarchButton("Delete project", variant: .danger) { isConfirming = true }
    .sheet(isPresented: $isConfirming) {
        VStack(alignment: .leading, spacing: 0) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                Image(systemName: "exclamationmark.triangle")
                    .foregroundStyle(theme.colors.dangerStrong)
                    .frame(width: 40, height: 40)
                    .background(theme.colors.dangerSubtle, in: Circle())
                    .accessibilityHidden(true)
                Text("Delete this project?").monarchTextStyle(.heading).accessibilityAddTraits(.isHeader)
                Text("This cannot be undone.").monarchTextStyle(.body).foregroundStyle(theme.colors.textMuted)
                VStack(alignment: .leading, spacing: theme.spacing.space1) {
                    ForEach(consequences, id: \.self) { line in
                        HStack(alignment: .firstTextBaseline, spacing: theme.spacing.space2) {
                            Text("\u{2022}")
                            Text(line)
                        }
                        .monarchTextStyle(.body)
                    }
                }
                .padding(.vertical, theme.spacing.space2)
                MonarchTextField("Type \("q3-launch") to confirm", text: $typed)
            }
            .padding(theme.spacing.space6)
            Divider()
            HStack(spacing: theme.spacing.space2) {
                Spacer()
                MonarchButton("Cancel", variant: .secondary) { isConfirming = false }
                MonarchButton("Delete project", variant: .danger) { isDeleted = true; isConfirming = false }
                    .disabled(typed != "q3-launch")
            }
            .padding(theme.spacing.space4)
            .background(theme.colors.bgSubtle)
        }
        .presentationDetents([.height(540)])
    }

MonarchButton("Delete workspace", variant: .danger) { isConfirming = true }
    .alert(
        "Type DELETE to confirm",
        isPresented: $isConfirming,
        actions: {
            TextField("DELETE", text: $phrase)
            Button("Delete", role: .destructive) { isDeleted = true }
                .disabled(phrase != "DELETE")
            Button("Cancel", role: .cancel) {}
        },
        message: {
            Text("The workspace and everything in it are deleted.")
        }
    )

